#include <cstdlib>
#include <iostream>
#include <new>
#include <string>
#include <string_view>
#include <vector>

long g_allocs = 0;  // every heap allocation passes through here
void* operator new(std::size_t n) {
    ++g_allocs;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

int main() {
    const std::string msg = "35=D|11=DESK7-20261122-000042|55=AAPL|44=19275|38=100";
    std::vector<std::string> copies;
    std::vector<std::string_view> views;
    copies.reserve(8);
    views.reserve(8);

    long before = g_allocs;
    std::size_t start = 0;
    while (start < msg.size()) {
        std::size_t bar = msg.find('|', start);
        if (bar == std::string::npos) {
            bar = msg.size();
        }
        copies.push_back(msg.substr(start, bar - start));
        start = bar + 1;
    }
    std::cout << "string fields: " << copies.size() << ", allocations " << g_allocs - before << '\n';

    before = g_allocs;
    std::string_view rest = msg;
    while (!rest.empty()) {
        const std::size_t bar = rest.find('|');
        views.push_back(rest.substr(0, bar));
        if (bar == std::string_view::npos) {
            break;
        }
        rest.remove_prefix(bar + 1);
    }
    std::cout << "view fields: " << views.size() << ", allocations " << g_allocs - before << '\n';
    for (std::string_view field : views) {
        std::cout << field << " (" << field.size() << ")\n";
    }
    std::cout << "sizeof: string " << sizeof(std::string) << ", string_view " << sizeof(std::string_view) << '\n';
    return 0;
}

