#include <iostream>
#include <string>
#include <string_view>

char g_buffer[64];  // a receive buffer, reused for every message

std::string_view receive(std::string_view wire) {
    const std::size_t n = wire.copy(g_buffer, sizeof g_buffer);  // the network would write here
    return std::string_view(g_buffer, n);
}

// The value of "tag=" in a message like "35=D|55=AAPL|44=19275", as a view into the message.
std::string_view value_of(std::string_view msg, std::string_view tag) {
    while (!msg.empty()) {
        const std::size_t bar = msg.find('|');
        const std::string_view field = msg.substr(0, bar);
        if (field.size() > tag.size() && field.substr(0, tag.size()) == tag && field[tag.size()] == '=') {
            return field.substr(tag.size() + 1);
        }
        if (bar == std::string_view::npos) {
            break;
        }
        msg.remove_prefix(bar + 1);
    }
    return {};
}

int main() {
    std::string_view msg = receive("35=D|55=AAPL|44=19275");
    const std::string_view symbol_view = value_of(msg, "55");
    const std::string symbol_copy(symbol_view);
    std::cout << "first:  view " << symbol_view << ", copy " << symbol_copy << '\n';

    msg = receive("35=D|55=MSFT|44=41010");  // the next message reuses the buffer
    std::cout << "second: view " << symbol_view << ", copy " << symbol_copy << '\n';
    std::cout << "value_of 44: " << value_of(msg, "44") << ", missing tag empty: " << value_of(msg, "99").empty() << '\n';
    return 0;
}

