#include <charconv>
#include <cstdint>
#include <iostream>
#include <optional>
#include <string_view>
#include <system_error>

void show(std::string_view s) {
    std::int64_t value = -1;
    const char* last = s.data() + s.size();
    const auto [ptr, ec] = std::from_chars(s.data(), last, value);
    std::cout << '"' << s << "\": ";
    if (ec == std::errc::invalid_argument) {
        std::cout << "no digits\n";
    } else if (ec == std::errc::result_out_of_range) {
        std::cout << "out of range\n";
    } else if (ptr != last) {
        std::cout << value << ", stopped at '" << *ptr << "'\n";
    } else {
        std::cout << value << '\n';
    }
}

// All of s as an integer with no sign, or nothing.
std::optional<std::int64_t> to_uint(std::string_view s) {
    if (s.empty() || s[0] == '-') {
        return std::nullopt;  // from_chars itself would accept a minus sign
    }
    std::int64_t value = 0;
    const char* last = s.data() + s.size();
    const auto [ptr, ec] = std::from_chars(s.data(), last, value);
    if (ec != std::errc{} || ptr != last) {
        return std::nullopt;
    }
    return value;
}

// "192.75" -> 19275 ticks of 0.01: up to 9 digits, a dot, exactly 2 decimals.
std::optional<std::int64_t> price_ticks(std::string_view s) {
    const std::size_t dot = s.find('.');
    if (dot == std::string_view::npos || dot > 9 || s.size() - dot != 3) {
        return std::nullopt;
    }
    const std::optional<std::int64_t> whole = to_uint(s.substr(0, dot));
    const std::optional<std::int64_t> cents = to_uint(s.substr(dot + 1));
    if (!whole.has_value() || !cents.has_value()) {
        return std::nullopt;
    }
    return *whole * 100 + *cents;
}

int main() {
    for (std::string_view s : {"100", "-40", "12abc", "abc", " 7", "+5", "99999999999999999999"}) {
        show(s);
    }
    for (std::string_view s : {"192.75", "41.10", "0.05", "192.7", "19275", "-0.50", "1.2x"}) {
        const std::optional<std::int64_t> t = price_ticks(s);
        std::cout << s << " -> " << (t.has_value() ? std::to_string(*t) : "invalid") << '\n';
    }
    return 0;
}

