#include <charconv>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <optional>
#include <sstream>
#include <string>
#include <string_view>

long g_allocs = 0;
void* operator new(std::size_t n) {
    ++g_allocs;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct NewOrder {
    std::string_view symbol;  // a view into the input
    std::int64_t price_ticks = 0;
    std::int64_t qty = 0;
};

bool to_int(std::string_view s, std::int64_t& out) {
    const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), out);
    return ec == std::errc{} && ptr == s.data() + s.size();
}

// "35=D|55=AAPL|44=19275|38=100" -> a NewOrder, or nothing if it's malformed.
std::optional<NewOrder> parse(std::string_view msg) {
    NewOrder order;
    bool is_new = false;
    while (!msg.empty()) {
        const std::size_t bar = msg.find('|');
        const std::string_view field = msg.substr(0, bar);
        msg.remove_prefix(bar == std::string_view::npos ? msg.size() : bar + 1);
        const std::size_t eq = field.find('=');
        std::int64_t tag = 0;
        if (eq == std::string_view::npos || !to_int(field.substr(0, eq), tag)) return std::nullopt;
        const std::string_view value = field.substr(eq + 1);
        if (tag == 35) is_new = (value == "D");
        else if (tag == 55) order.symbol = value;
        else if (tag == 44 && !to_int(value, order.price_ticks)) return std::nullopt;
        else if (tag == 38 && !to_int(value, order.qty)) return std::nullopt;
    }
    if (!is_new || order.symbol.empty() || order.price_ticks <= 0 || order.qty <= 0) return std::nullopt;
    return order;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::ostringstream all;
    all << std::cin.rdbuf();  // the whole input in one read
    const std::string input = all.str();

    const long before = g_allocs;
    std::string_view rest = input;
    int bad = 0;
    while (!rest.empty()) {
        const std::size_t nl = rest.find('\n');
        const std::string_view line = rest.substr(0, nl);
        rest.remove_prefix(nl == std::string_view::npos ? rest.size() : nl + 1);
        const std::optional<NewOrder> order = parse(line);
        if (order.has_value()) {
            std::cout << order->symbol << ' ' << order->qty << " @ " << order->price_ticks << '\n';
        } else {
            ++bad;
        }
    }
    std::cout << "rejected " << bad << ", allocations while parsing " << g_allocs - before << '\n';
    return 0;
}

